-- Load pywal colors if present, with defaults
local function get_wal_color(var_name, fallback)
    local home = os.getenv("HOME") or "/home/stammererone"
    local f = io.open(home .. "/.cache/wal/colors-hyprland.conf", "r")
    if not f then return fallback end
    for line in f:lines() do
        local k, v = line:match("^%$([%w_]+)%s*=%s*(.+)$")
        if k == var_name then
            f:close()
            return v
        end
    end
    f:close()
    return fallback
end

